begin;
create table private.owner_catalog_edit_commands(request_id uuid primary key,actor_id uuid not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp());
alter table private.owner_catalog_edit_commands enable row level security;
revoke all on private.owner_catalog_edit_commands from public,anon,authenticated,service_role;
create trigger immutable_owner_catalog_edit before update or delete on private.owner_catalog_edit_commands for each row execute function private.owner_tax_immutable();
create function private.owner_catalog_revision(p_item uuid)returns text language sql stable security invoker set search_path=pg_catalog as $$select md5((to_jsonb(c)-array['stock_quantity','updated_at'])::text)from public.business_catalog_items c where c.item_id=p_item$$;
revoke all on function private.owner_catalog_revision(uuid)from public,anon,authenticated,service_role;
create function private.get_owner_catalog_items(p_branch uuid default null,p_after uuid default null)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare b uuid;items jsonb;begin
 if not coalesce(private.has_live_invoice_session(),false)or private.active_staff_role()is distinct from'owner'then raise exception 'Current owner session required'using errcode='42501';end if;
 b:=p_branch;if b is null then select branch_id into b from public.business_branches where is_default and is_active;end if;perform private.require_owner_tax_branch(b);
 select coalesce(jsonb_agg(to_jsonb(x)order by item_id),'[]')into items from(select c.item_id,c.item_type,c.name,c.name_en,c.price,c.duration_minutes,c.is_active,c.is_public,c.image_url,c.category,c.stock_quantity,private.owner_catalog_revision(c.item_id)revision from public.business_catalog_items c where branch_id=b and(p_after is null or c.item_id>p_after)order by c.item_id limit 101)x;
 return jsonb_build_object('branch',b,'items',case when jsonb_array_length(items)>100 then items-100 else items end,'has_more',jsonb_array_length(items)>100);end$$;
create function private.save_owner_catalog_item(p_request uuid,p_branch uuid,p_item uuid,p_expected_revision text,p_spec jsonb,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare actor uuid;payload jsonb;prior private.owner_catalog_edit_commands;original public.business_catalog_items;id uuid:=coalesce(p_item,gen_random_uuid());result jsonb;begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_request is null or jsonb_typeof(p_spec)is distinct from'object'or(select count(*)from jsonb_object_keys(p_spec))<>9 or not(p_spec?'item_type'and p_spec?'name'and p_spec?'name_en'and p_spec?'price'and p_spec?'duration_minutes'and p_spec?'is_active'and p_spec?'is_public'and p_spec?'image_url'and p_spec?'category')or p_spec->>'item_type'is null or p_spec->>'item_type'not in('service','product')or jsonb_typeof(p_spec->'name')is distinct from'string'or jsonb_typeof(p_spec->'name_en')is distinct from'string'or length(trim(p_spec->>'name'))not between 1 and 160 or length(trim(p_spec->>'name_en'))not between 1 and 160 or jsonb_typeof(p_spec->'price')is distinct from'number'or(p_spec->>'price')::numeric<0 or(p_spec->>'price')::numeric<>round((p_spec->>'price')::numeric,2)or jsonb_typeof(p_spec->'duration_minutes')is distinct from'number'or(p_spec->>'duration_minutes')::numeric not between 1 and 1440 or(p_spec->>'duration_minutes')::numeric<>trunc((p_spec->>'duration_minutes')::numeric)or jsonb_typeof(p_spec->'is_active')is distinct from'boolean'or jsonb_typeof(p_spec->'is_public')is distinct from'boolean'or(p_spec->>'category'is not null and(jsonb_typeof(p_spec->'category')is distinct from'string'or length(p_spec->>'category')>100))or(p_spec->>'image_url'is not null and(jsonb_typeof(p_spec->'image_url')is distinct from'string'or length(p_spec->>'image_url')>2048 or p_spec->>'image_url'!~'^https://[^[:space:]]+$'))or length(trim(coalesce(p_reason,'')))not between 5 and 500 then raise exception 'Explicit valid bilingual catalogue item required'using errcode='22023';end if;
 payload:=jsonb_build_object('branch',p_branch,'item',p_item,'revision',p_expected_revision,'spec',p_spec,'reason',trim(p_reason));perform pg_advisory_xact_lock(hashtextextended('owner-catalog-edit:'||p_request,0));select *into prior from private.owner_catalog_edit_commands where request_id=p_request;
 if found then if prior.actor_id<>actor or prior.payload<>payload then raise exception 'Request payload mismatch'using errcode='22023';end if;return prior.result;end if;
 if p_item is not null then
 select *into original from public.business_catalog_items where item_id=p_item and branch_id=p_branch for update;
 if not found then raise exception 'Catalogue item outside owner branch'using errcode='42501';end if;
 if private.owner_catalog_revision(p_item)is distinct from p_expected_revision then raise exception 'Catalogue item changed; reload before saving'using errcode='40001';end if;
 if original.item_type<>p_spec->>'item_type'then raise exception 'Existing item kind is retained; create a new item instead'using errcode='22023';end if;
 update public.business_catalog_items set name=trim(p_spec->>'name'),name_en=trim(p_spec->>'name_en'),price=(p_spec->>'price')::numeric,duration_minutes=(p_spec->>'duration_minutes')::integer,is_active=(p_spec->>'is_active')::boolean,is_public=(p_spec->>'is_public')::boolean,image_url=p_spec->>'image_url',category=p_spec->>'category',updated_at=clock_timestamp()where item_id=p_item;
 else
 if p_expected_revision is not null then raise exception 'New item has no prior revision'using errcode='22023';end if;
 insert into public.business_catalog_items(item_id,branch_id,item_type,name,name_en,price,duration_minutes,is_active,is_public,image_url,category,stock_quantity)values(id,p_branch,p_spec->>'item_type',trim(p_spec->>'name'),trim(p_spec->>'name_en'),(p_spec->>'price')::numeric,(p_spec->>'duration_minutes')::integer,(p_spec->>'is_active')::boolean,(p_spec->>'is_public')::boolean,p_spec->>'image_url',p_spec->>'category',0);
 end if;
 result:=jsonb_build_object('item_id',id,'revision',private.owner_catalog_revision(id),'issued_invoices_unchanged',true);
 insert into private.owner_catalog_edit_commands values(p_request,actor,payload,result,clock_timestamp());insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,before_data,after_data)values(actor::text,actor,'owner_catalog_item_saved','catalog_item',id::text,p_branch,to_jsonb(original),p_spec||result);return result;end$$;
create function public.get_owner_catalog_items(p_branch uuid default null,p_after uuid default null)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.get_owner_catalog_items(p_branch,p_after)$$;
create function public.save_owner_catalog_item(p_request uuid,p_branch uuid,p_item uuid,p_expected_revision text,p_spec jsonb,p_reason text)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.save_owner_catalog_item(p_request,p_branch,p_item,p_expected_revision,p_spec,p_reason)$$;
revoke all on function private.get_owner_catalog_items(uuid,uuid),public.get_owner_catalog_items(uuid,uuid),private.save_owner_catalog_item(uuid,uuid,uuid,text,jsonb,text),public.save_owner_catalog_item(uuid,uuid,uuid,text,jsonb,text)from public,anon,authenticated,service_role;
grant execute on function private.get_owner_catalog_items(uuid,uuid),public.get_owner_catalog_items(uuid,uuid),private.save_owner_catalog_item(uuid,uuid,uuid,text,jsonb,text),public.save_owner_catalog_item(uuid,uuid,uuid,text,jsonb,text)to authenticated;
notify pgrst,'reload schema';commit;
